    "publishedAt": "27/11/2026 às 12:49",
    "category": "Justiça",
    "ingestedAt": "27/11/2026 às 15:42",
    "imageUrl": "https://imagens.ebc.com.br/M1elYhE0d0_VTI6OwGADwd03Ets=/1170x700/smart/https://agenciabrasil.ebc.com.br/sites/default/files/thumbnails/image/2025/09/11/_mg_0886.jpg?itok=0uz6vOd8",
