    "sourceUrl": "https://sociedadeativa.github.io/",
    "articleUrl": "https://sociedadeativa.github.io/noticias/whatsapp-figurinhas-com-som-sem-borda-branca/",
    "publishedAt": "25/11/2026 às 09:20",
